// Read fixed known sources only. Never return any configuration value, even unknown fields.
const fs=require('node:fs'),path=require('node:path');
module.exports=function inspect(root){
 const sources=[['IRIS / Web / SFTP','.agents/config/project-env.json','当前工程'],['开发方式','.agents/config/iris-development.json','当前工程'],['MCP 服务','.mcp.json','当前工程'],['受管 MCP backend','.agents/config/iris-session-backend.json','当前工程'],['BOS 查询与日志',process.env.BOS_MCP_CONFIG,'共享个人配置'],['知识提供方与 Key',process.env.KNOWLEDGE_RAG_CONFIG,'共享个人配置']];
 const domains=sources.map(([name,file,scope])=>{const out={name,scope,source:scope==='当前工程'?file:name.startsWith('BOS')?'BOS_MCP_CONFIG':'KNOWLEDGE_RAG_CONFIG',fields:[]};if(!file)return {...out,status:'当前进程未绑定来源'};try{const raw=fs.readFileSync(path.isAbsolute(file)?file:path.join(root,file),'utf8').replace(/^\uFEFF/,'');const data=JSON.parse(raw);function walk(v,p){if(v&&typeof v==='object'){for(const [k,x]of Object.entries(v))walk(x,p?p+'.'+k:k)}else out.fields.push({key:p,status:v===null||v===''?'未填写':'已设置',sensitive:/password|token|key|cookie|secret/i.test(p)});}walk(data,'');return {...out,status:'已真实读取'}}catch(e){return {...out,status:e.code==='ENOENT'?'来源文件不存在':'读取或格式解析失败，未改动原文件'}}});
 const profile=path.join(root,'.agents/config/plugin_profile.md');let plugins=[];try{const raw=fs.readFileSync(profile,'utf8');plugins=raw.split(/\r?\n/).filter(l=>/^\s*\|/.test(l)&&/enabled|disabled|available|pending/i.test(l)).map(l=>{const cells=l.split('|').map(x=>x.trim().replace(/`/g,''));return {name:cells.find(x=>/^[a-z][a-z0-9-]+$/.test(x)&&!['enabled','disabled','available','pending'].includes(x)),status:cells.find(x=>/^(enabled|disabled|available|pending)$/i.test(x))}}).filter(x=>x.name&&x.status)}catch{}
 const profiles=['iris_project_profile.md','project_context_profile.md','cure_form_profile.md','demand_delivery_profile.md','i18n_project_profile.md'].map(name=>({name,exists:fs.existsSync(path.join(root,'.agents/config',name))}));
 const clients=[['Codex',['AGENTS.md','.codex/agents']],['Claude Code',['CLAUDE.md','.claude']],['OpenCode',['opencode.json','.opencode']],['CodeBuddy',['CODEBUDDY.md','.codebuddy']],['WorkBuddy',['.workbuddy']],['Hermes',['.hermes']]].map(([name,paths])=>({name,entries:paths.filter(p=>fs.existsSync(path.join(root,p))),status:'尚未验证宿主加载'}));
 const indexes=['index.sqlite','company.sqlite','local.sqlite'].map(name=>{try{const st=fs.statSync(path.join(root,'.agents/.knowledge-cache',name));return {name,exists:true,bytes:st.size,updated:st.mtime.toISOString()}}catch{return {name,exists:false}}});
 const receipts=[];const dir=path.join(root,'.ai-dev-config-backups');
 if(fs.existsSync(dir))for(const id of fs.readdirSync(dir).filter(n=>/^[a-f0-9-]{36}$/.test(n))){try{const f=path.join(dir,id,'receipt.json');const r=JSON.parse(fs.readFileSync(f,'utf8'));if(r.tool==='ai-dev-project')receipts.push({id,state:r.state,files:r.entries?.length||0,updated:fs.statSync(f).mtime.toISOString()})}catch{}}
 return {name:path.basename(root),checkedAt:new Date().toISOString(),domains,plugins,profiles,clients,indexes,receipts,hasFramework:fs.existsSync(path.join(root,'.agents'))};
};
